INSERT INTO lessons (id, category_id, title, slug, short_description, content, difficulty, duration_minutes, sort_order, published) VALUES
('20000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000001', 'Как начать заниматься', 'kak-nachat-zanimatsya', 'Безопасный старт в калистенике.', 'Начните с оценки текущей подготовки, регулярной разминки и небольшой нагрузки.', 'beginner', 8, 1, true),
('20000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000001', 'Прогрессия нагрузки', 'progressiya-nagruzki', 'Как расти без перегрузки.', 'Увеличивайте объём постепенно и оставляйте время на восстановление.', 'beginner', 10, 2, true),
('20000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000002', 'Техника отжиманий', 'tekhnika-otzhimaniy', 'Положение корпуса и траектория движения.', 'Держите корпус прямым, контролируйте опускание и не разводите локти слишком широко.', 'beginner', 7, 1, true),
('20000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000002', 'Техника подтягиваний', 'tekhnika-podtyagivaniy', 'Чистое подтягивание без рывков.', 'Начинайте движение лопатками, избегайте раскачки и контролируйте опускание.', 'intermediate', 9, 2, true),
('20000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000003', 'Разминка плеч', 'razminka-plech', 'Подготовка плечевого пояса.', 'Выполните круговые движения, активацию лопаток и лёгкую мобилизацию.', 'beginner', 6, 1, true),
('20000000-0000-0000-0000-000000000006', '10000000-0000-0000-0000-000000000003', 'Разминка запястий', 'razminka-zapyastiy', 'Подготовка запястий к опоре.', 'Мягко разомните кисти и увеличивайте амплитуду постепенно.', 'beginner', 5, 2, true),
('20000000-0000-0000-0000-000000000007', '10000000-0000-0000-0000-000000000004', 'Восстановление после тренировки', 'vosstanovlenie-posle-trenirovki', 'Сон, питание и лёгкая активность.', 'Дайте организму сон, белок и прогулку вместо лишней тяжёлой тренировки.', 'beginner', 8, 1, true),
('20000000-0000-0000-0000-000000000008', '10000000-0000-0000-0000-000000000004', 'Когда делать перерыв', 'kogda-delat-pereryv', 'Признаки, что нагрузку нужно снизить.', 'Боль в суставах, ухудшение техники и хроническая усталость требуют отдыха.', 'beginner', 7, 2, true),
('20000000-0000-0000-0000-000000000009', '10000000-0000-0000-0000-000000000002', 'Планка без ошибок', 'planka-bez-oshibok', 'Стабильный корпус и дыхание.', 'Сохраняйте нейтральную спину, напрягайте мышцы живота и дышите ровно.', 'beginner', 6, 3, true),
('20000000-0000-0000-0000-000000000010', '10000000-0000-0000-0000-000000000002', 'Брусья: безопасная глубина', 'brusya-bezopasnaya-glubina', 'Как выполнять отжимания на брусьях.', 'Опускайтесь до комфортной глубины, не теряя контроля над плечами.', 'intermediate', 8, 4, true);
INSERT INTO exercises (id, name, slug, description, instructions, common_mistakes, difficulty, muscle_groups, equipment) VALUES
('30000000-0000-0000-0000-000000000001', 'Отжимания', 'otzhimaniya', 'Базовое упражнение на грудь и трицепс.', 'Корпус прямой, ладони под плечами, опускайтесь контролируемо.', 'Провисание таза и неполная амплитуда.', 'beginner', ARRAY['грудь','трицепс','плечи'], ARRAY[]::text[]),
('30000000-0000-0000-0000-000000000002', 'Приседания', 'prisedaniya', 'Базовое упражнение для ног.', 'Отводите таз назад, колени направляйте по линии стоп.', 'Сведение коленей и отрыв пяток.', 'beginner', ARRAY['квадрицепс','ягодицы'], ARRAY[]::text[]),
('30000000-0000-0000-0000-000000000003', 'Планка', 'planka', 'Статическое упражнение на мышцы корпуса.', 'Опирайтесь на предплечья, удерживайте нейтральную спину.', 'Подъём таза или прогиб поясницы.', 'beginner', ARRAY['кор','плечи'], ARRAY[]::text[]),
('30000000-0000-0000-0000-000000000004', 'Австралийские подтягивания', 'avstraliyskie-podtyagivaniya', 'Горизонтальная тяга для подготовки к подтягиваниям.', 'Тяните грудь к перекладине, держите корпус жёстким.', 'Рывки корпусом и провисание таза.', 'beginner', ARRAY['спина','бицепс'], ARRAY['низкая перекладина']),
('30000000-0000-0000-0000-000000000005', 'Подтягивания', 'podtyagivaniya', 'Вертикальная тяга на перекладине.', 'Начинайте с движения лопаток и тянитесь грудью вверх.', 'Раскачка и неполное разгибание рук.', 'intermediate', ARRAY['спина','бицепс'], ARRAY['перекладина']),
('30000000-0000-0000-0000-000000000006', 'Отжимания на брусьях', 'otzhimaniya-na-brusyah', 'Упражнение на грудь и трицепс.', 'Контролируйте плечи и выполняйте плавную амплитуду.', 'Слишком глубокое опускание с потерей контроля.', 'intermediate', ARRAY['грудь','трицепс'], ARRAY['брусья']),
('30000000-0000-0000-0000-000000000007', 'Ягодичный мост', 'yagodichnyy-most', 'Укрепление ягодиц и задней поверхности тела.', 'Поднимайте таз за счёт ягодиц, не переразгибайте поясницу.', 'Толчок поясницей вместо работы ягодиц.', 'beginner', ARRAY['ягодицы','задняя поверхность бедра'], ARRAY[]::text[]),
('30000000-0000-0000-0000-000000000008', 'Вис на перекладине', 'vis-na-perekladine', 'Укрепление хвата и плеч.', 'Сохраняйте активные плечи и ровное дыхание.', 'Пассивное зависание с дискомфортом в плечах.', 'beginner', ARRAY['предплечья','плечи'], ARRAY['перекладина']),
('30000000-0000-0000-0000-000000000009', 'Негативные подтягивания', 'negativnye-podtyagivaniya', 'Контролируемое опускание для развития тяги.', 'Поднимитесь с опоры и опускайтесь 3–5 секунд.', 'Быстрое падение вниз.', 'beginner', ARRAY['спина','бицепс'], ARRAY['перекладина','опора']),
('30000000-0000-0000-0000-000000000010', 'Скапулярные отжимания', 'skapulyarnye-otzhimaniya', 'Активация лопаток в упоре.', 'Не сгибайте руки, двигайте только лопатками.', 'Сгибание локтей и округление спины.', 'beginner', ARRAY['плечи','кор'], ARRAY[]::text[]);
